class LruCache<K, V>(private val capacity: Int) {
    // accessOrder = true moves an entry to the end whenever it is read.
    private val map = object : LinkedHashMap<K, V>(16, 0.75f, true) {
        override fun removeEldestEntry(eldest: MutableMap.MutableEntry<K, V>?) =
            size > capacity
    }

    fun get(key: K): V? = map[key]
    fun put(key: K, value: V) { map[key] = value }
}

Find two numbers that add up to a target.code:
fun twoSum(numbers: IntArray, target: Int): Pair<Int, Int>? {
    val seen = HashMap<Int, Int>()              // value -> index
    numbers.forEachIndexed { i, n ->
        seen[target - n]?.let { return it to i }
        seen[n] = i
    }
    return null
}

Longest substring without repeating char.code:
fun longestUnique(text: String): Int {
    val last = HashMap<Char, Int>()
    var start = 0
    var best = 0
    text.forEachIndexed { i, c ->
        last[c]?.let { start = maxOf(start, it + 1) }
        last[c] = i
        best = maxOf(best, i - start + 1)
    }
    return best
}

Count islands in a grid..code:
fun countIslands(grid: Array<CharArray>): Int {
    val seen = HashSet<Pair<Int, Int>>()
    var islands = 0
    for (r in grid.indices) for (c in grid[r].indices) {
        if (grid[r][c] != '1' || !seen.add(r to c)) continue
        islands++
        val queue = ArrayDeque(listOf(r to c))
        while (queue.isNotEmpty()) {
            val (y, x) = queue.removeFirst()
            for ((ny, nx) in listOf(y - 1 to x, y + 1 to x, y to x - 1, y to x + 1)) {
                if (grid.getOrNull(ny)?.getOrNull(nx) == '1' && seen.add(ny to nx)) {
                    queue.add(ny to nx)
                }
            }
        }
    }
    return islands
}

Top K frequent elements?.code:
fun topK(numbers: IntArray, k: Int): List<Int> {
    val counts = numbers.asList().groupingBy { it }.eachCount()
    val heap = PriorityQueue<Map.Entry<Int, Int>>(compareBy { it.value })
    for (entry in counts.entries) {
        heap.add(entry)
        if (heap.size > k) heap.poll()          // drop the least frequent
    }
    return heap.map { it.key }
}

Write a debounce function with coroutine.code:
fun <T> debounce(
    waitMs: Long,
    scope: CoroutineScope,
    action: suspend (T) -> Unit,
): (T) -> Unit {
    var job: Job? = null
    return { value ->
        job?.cancel()
        job = scope.launch {
            delay(waitMs)
            action(value)
        }
    }
}

